sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    // Add your code here
    var year1 = source.u_baujahr_beginn;
    var year2 = source.u_baujahr_ende;
    if (year1 && year1.length === 4 && !isNaN(parseInt(year1))) {
        gs.info(year1 + '-01-01');
        gs.info(typeof(year1));
        target.production_year_from = year1 + '-01-01'; // No time part needed
        target.production_year_to = year2 + '-01-01'; // No time part needed
    }
    gs.info(year1 + '-01-01'); // leave empty if invalid
    gs.info(typeof(year1));
    target.production_year_from = year1 + '-01-01'; // No time part needed
    target.production_year_to = year2 + '-01-01'; // No time part needed

})(source, map, log, target);
